import {ReadinessGate,RestTimer,weeklyProgress} from './training.js';
import {guidePose} from './guides.js';

import './offline.js';

import {EXERCISES,RepCounter,HoldCounter,poseMeasurement,angle} from './engine.js';

const $=id=>document.getElementById(id), video=$('video'),canvas=$('pose-canvas'),ctx=canvas.getContext('2d'),chart=$('chart'),cx=chart.getContext('2d');

const readiness=new ReadinessGate(),rest=new RestTimer();
let checkingCamera=false;
let completedSets=[],betweenSets=false;
let exercise='squat',counter=new RepCounter(exercise),mode=null,paused=false,busy=false,stream=null,model=null,lastFrame=-1,started=0,elapsed=0,lastTick=0,demoTime=0,lastSpeak=0,lastSample=0,history=[],samples=[],confidenceSum=0,confidenceN=0,toastTimer;

try{history=JSON.parse(localStorage.getItem('fitvision.sessions.v1')||'[]');if(!Array.isArray(history))history=[];}catch{history=[];}

const connections=[[11,12],[11,13],[13,15],[12,14],[14,16],[11,23],[12,24],[23,24],[23,25],[25,27],[24,26],[26,28],[27,31],[28,32]];

const PROFILE_KEY='exercise.profile.v1';
function loadProfile(){try{return JSON.parse(localStorage.getItem(PROFILE_KEY)||'null');}catch{return null;}}
function renderProfile(profile){
  $('profile-gate').hidden=!!profile;
  $('profile-welcome').textContent=profile?`Hi, ${profile.name}`:'';
  $('profile-logout').hidden=!profile;
}
renderProfile(loadProfile());
$('profile-form').onsubmit=e=>{
  e.preventDefault();
  const name=$('profile-name').value.trim(),email=$('profile-email').value.trim();
  if(!name)return;
  localStorage.setItem(PROFILE_KEY,JSON.stringify({name,email}));
  renderProfile({name,email});
  toast(`Welcome, ${name}.`);
};
$('profile-logout').onclick=()=>{
  localStorage.removeItem(PROFILE_KEY);
  $('profile-name').value='';$('profile-email').value='';
  renderProfile(null);
};

function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}

function feedback(message,read=false){if($('feedback').textContent!==message)$('feedback').textContent=message;if(read)speak(message);}

let voicePrefs={};try{voicePrefs=JSON.parse(localStorage.getItem('exercise.voice')||'{}')||{};}catch{}

$('voice-rate').value=voicePrefs.rate||.95;$('voice-pitch').value=voicePrefs.pitch||1;$('voice').checked=!!voicePrefs.enabled;

function saveVoice(){try{localStorage.setItem('exercise.voice',JSON.stringify({name:$('voice-select').value,rate:$('voice-rate').value,pitch:$('voice-pitch').value,enabled:$('voice').checked}));}catch{}}

function voices(){if(!('speechSynthesis'in window)){$('voice').disabled=true;$('voice-note').textContent='Speech is unavailable in this browser. Written coaching remains available.';return;}const selected=$('voice-select').value||voicePrefs.name;const list=speechSynthesis.getVoices().filter(v=>(navigator.onLine&&!$('offline-voices').checked)||v.localService);$('voice-select').replaceChildren(new Option('Device default',''));list.forEach(v=>$('voice-select').add(new Option(`${v.name} · ${v.lang}${v.localService?' · offline':' · internet required'}`,v.name)));if(list.some(v=>v.name===selected))$('voice-select').value=selected;if(!$('voice-select').value){const local=list.find(v=>v.localService&&v.lang.startsWith('en'))||list.find(v=>v.localService);if(local)$('voice-select').value=local.name;}$('voice-note').textContent=list.length?`${list.length} voices available. Preview a voice to hear it. Offline voices run on your device.`:'No matching voices found. Install a speech voice in your device language settings, then refresh this list. Written coaching still works.';}

voices();if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=voices;

window.addEventListener('offline',voices);window.addEventListener('online',voices);

for(const id of ['voice-select','voice-rate','voice-pitch'])$(id).onchange=saveVoice;

$('voice-preview').onclick=()=>{lastSpeak=-Infinity;speak('Ready when you are. Let’s make every movement count.',true);};

function speak(message,preview=false){if((preview||$('voice').checked)&&'speechSynthesis'in window&&performance.now()-lastSpeak>6500){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(message);u.rate=Number($('voice-rate').value);u.pitch=Number($('voice-pitch').value);u.voice=speechSynthesis.getVoices().find(v=>v.name===$('voice-select').value)||(!navigator.onLine?speechSynthesis.getVoices().find(v=>v.localService):null)||null;if(!navigator.onLine&&!u.voice?.localService){$('voice-note').textContent='Select an offline voice to hear coaching without internet.';return;}u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('Voice could not play. Try another installed voice.');};speechSynthesis.speak(u);lastSpeak=performance.now();}}

function setExercise(key){if(mode||busy){toast('Finish the current session before changing exercise.');return;}exercise=key;rest.clear();$('rest-countdown').hidden=true;completedSets=[];betweenSets=false;renderSets();$('guide-video').src=`./guides/${key}.webm`;$('guide-title').textContent=EXERCISES[key].name+' · movement guide';$('metric-unit').textContent=key==='plank'?'HOLD SECONDS':'REPETITIONS';$('target-label').textContent=key==='plank'?'Hold target (seconds)':'Rep target';$('target').value=key==='plank'?30:10;document.querySelectorAll('[data-exercise]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.exercise===key)));counter=key==='plank'?new HoldCounter():new RepCounter(key);document.querySelectorAll('[data-exercise]').forEach(b=>b.classList.toggle('selected',b.dataset.exercise===key));$('exercise-type').textContent=EXERCISES[key].type;$('joint-label').textContent=EXERCISES[key].joint;$('form-tips').replaceChildren(...EXERCISES[key].tips.map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));$('camera-hint').textContent=['press','pullup'].includes(key)?'Front view · Arms visible · Good lighting':key==='curl'?'Side view · Arm fully visible · Good lighting':'Side view · Full body visible · Good lighting';feedback(EXERCISES[key].setup);renderMetrics();}

function setCount(){return Math.max(1,Math.min(20,Math.round(Number($('sets').value)||1)));}
function setSets(n){if(mode)return;completedSets=[];betweenSets=false;$('sets').value=Math.max(1,Math.min(20,Math.round(n)));renderSets();}
function renderSets(){const total=setCount();$('set-progress').textContent=completedSets.length>=total?`All ${total} sets complete`:`Set ${Math.min(completedSets.length+1,total)} of ${total}`;$('next-set').hidden=!mode||!betweenSets||completedSets.length>=total;$('set-note').textContent=betweenSets?(completedSets.length>=total?'Finish session to save your workout.':'Set complete. Rest, then start when ready.'):'Reach your target, then rest before the next set.';}
function completeSet(){if(betweenSets)return;completedSets.push(exercise==='plank'?Math.floor(counter.seconds):counter.reps);betweenSets=true;paused=true;checkingCamera=false;$('readiness-panel').hidden=true;rest.start(completedSets.length<setCount()?Number($('rest-seconds').value):0,performance.now());$('pause').disabled=true;$('session-status').textContent='Set complete';document.body.classList.remove('running');renderSets();lastSpeak=-Infinity;feedback(completedSets.length>=setCount()?'All sets complete. Finish the session to save your workout.':'Set complete. Take a rest, then choose Start next set.',true);}
function nextSet(){if(!mode||!betweenSets||completedSets.length>=setCount())return;counter=exercise==='plank'?new HoldCounter():new RepCounter(exercise);betweenSets=false;paused=false;rest.clear();$('rest-countdown').hidden=true;startReadiness();demoTime=0;samples=[];lastTick=performance.now();$('pause').disabled=false;$('pause').textContent='Pause';$('session-status').textContent=mode==='demo'?'Guided demo':'Live session';document.body.classList.add('running');renderSets();renderMetrics();feedback(EXERCISES[exercise].setup,true);}
function target(){return Math.max(1,Math.min(100,Math.round(Number($('target').value))||10));}function setTarget(n){$('target').value=Math.max(1,Math.min(100,Math.round(n)));renderMetrics();}

function renderMetrics(conf=null){$('reps').textContent=exercise==='plank'?Math.floor(counter.seconds):counter.reps;$('phase').textContent=counter.phase;$('target-display').textContent='/ '+target();$('rep-progress').style.width=Math.min(100,(exercise==='plank'?counter.seconds:counter.reps)/target()*100)+'%';if(conf!==null){$('confidence').textContent=Math.round(conf*100);$('confidence-note').textContent=conf>=.65?'Required joints visible':'Improve camera framing';}}

function timeText(ms){const s=Math.floor(ms/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}

function begin(source){$('camera-help').hidden=true;mode=source;paused=false;rest.clear();$('rest-countdown').hidden=true;startReadiness();$('rest-seconds').disabled=true;completedSets=[];betweenSets=false;renderSets();for(const id of ['sets','sets-minus','sets-plus'])$(id).disabled=true;counter=exercise==='plank'?new HoldCounter():new RepCounter(exercise);elapsed=0;$('timer').textContent='00:00';demoTime=0;samples=[];confidenceSum=0;confidenceN=0;started=Date.now();lastTick=performance.now();lastSample=0;$('camera-empty').hidden=true;$('angle-chip').hidden=false;$('pause').disabled=false;$('pause').textContent='Pause';$('finish').disabled=false;$('session-status').textContent=source==='demo'?'Guided demo':'Live session';$('camera-status').textContent=source==='demo'?'SIMULATED DEMO':'LIVE CAMERA';$('camera-status').classList.add('live');$('source-label').textContent=source==='demo'?'SYNTHETIC POSE · NO CAMERA':'MEDIAPIPE POSE';document.body.classList.add('running');feedback(source==='demo'?'This guided demo uses simulated landmarks to demonstrate the same angle and repetition rules used by the camera.':EXERCISES[exercise].setup,true);$('target').disabled=true;$('target-minus').disabled=true;$('target-plus').disabled=true;renderMetrics();}

async function enableCamera(){if(busy||mode)return;busy=true;$('start-camera').disabled=true;$('start-demo').disabled=true;$('start-camera').textContent='Loading pose model…';try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera requires localhost or HTTPS. Open the app using Start Exercise Intelligence.cmd.');if(!model){const {FilesetResolver,PoseLandmarker}=await import('./vendor/vision_bundle.mjs');const files=await FilesetResolver.forVisionTasks('./vendor/wasm');model=await PoseLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'./vendor/pose_landmarker_lite.task',delegate:'CPU'},runningMode:'VIDEO',numPoses:1,minPoseDetectionConfidence:.6,minPosePresenceConfidence:.6,minTrackingConfidence:.6});}$('start-camera').textContent='Allow camera access…';stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:960},height:{ideal:600},facingMode:'user'},audio:false});video.srcObject=stream;await video.play();lastFrame=-1;begin('camera');}catch(err){stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;const message=err.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in your browser, or use the guided demo.':err.name==='NotFoundError'?'No camera found. Connect a webcam, or use the guided demo.':err.name==='NotReadableError'?'Your camera is busy. Close other camera apps and try again.':err.message?.includes('localhost')?err.message:'Could not start pose tracking. Reload and try again, or use the guided demo.';$('camera-help').hidden=false;feedback(message);toast(message);}finally{busy=false;$('start-camera').disabled=false;$('start-demo').disabled=false;$('start-camera').textContent='◉ Enable camera';}}

function stop(save=true){if(!mode)return;const source=mode;const results=[...completedSets];if(!betweenSets)results.push(exercise==='plank'?Math.floor(counter.seconds):counter.reps);const total=results.reduce((a,b)=>a+b,0);if(save){history.unshift({id:crypto.randomUUID(),date:new Date(started).toISOString(),exercise,source,reps:exercise==='plank'?0:total,holdSeconds:exercise==='plank'?total:null,target:target(),setsTarget:setCount(),setsCompleted:completedSets.length,setResults:results,duration:Math.round(elapsed/1000),confidence:confidenceN?Math.round(confidenceSum/confidenceN*100):null});try{localStorage.setItem('fitvision.sessions.v1',JSON.stringify(history));toast('Session saved to workout history.');}catch{toast('Session is available now, but browser storage is full. Export your history.');}}mode=null;paused=false;checkingCamera=false;rest.clear();$('rest-countdown').hidden=true;$('readiness-panel').hidden=true;$('rest-seconds').disabled=false;$('next-set').hidden=true;for(const id of ['sets','sets-minus','sets-plus'])$(id).disabled=false;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;ctx.clearRect(0,0,canvas.width,canvas.height);$('camera-empty').hidden=false;$('angle-chip').hidden=true;$('camera-status').textContent='CAMERA OFF';$('camera-status').classList.remove('live');$('source-label').textContent='POSE ANALYSIS';$('tracking-status').textContent='Session complete';$('pause').disabled=true;$('pause').textContent='Pause';$('finish').disabled=true;$('target').disabled=false;$('target-minus').disabled=false;$('target-plus').disabled=false;$('session-status').textContent='Session saved';document.body.classList.remove('running');if('speechSynthesis'in window)speechSynthesis.cancel();feedback(`${source==='demo'?'Demo':'Workout'} complete. ${exercise==='plank'?total+' seconds held':total+' repetitions'} in ${timeText(elapsed)}. Your session is in workout history.`);}

function pause(){if(!mode||betweenSets)return;paused=!paused;counter.resetCycle();if(!paused)startReadiness();$('pause').textContent=paused?'Resume':'Pause';$('session-status').textContent=paused?'Paused':mode==='demo'?'Guided demo':'Live session';$('tracking-status').textContent=paused?'Paused · return to start position when resuming':'Find the extended start position';document.body.classList.toggle('running',!paused);if('speechSynthesis'in window)speechSynthesis.cancel();renderMetrics();}

function startReadiness(){readiness.reset();checkingCamera=mode==='camera';$('readiness-panel').hidden=!checkingCamera;$('readiness-progress').value=0;$('readiness-title').textContent='Camera position check';$('readiness-text').textContent=EXERCISES[exercise].setup;}
function updateRest(now){if(!mode||!betweenSets||completedSets.length>=setCount())return;const remaining=rest.remaining(now);$('rest-countdown').hidden=false;$('rest-countdown').textContent=remaining?`Rest ${timeText(remaining*1000)}`:'Rest complete';$('next-set').textContent=remaining?'Skip rest & start next set':'Start next set';if(!remaining&&!rest.announced){rest.announced=true;lastSpeak=-Infinity;feedback('Rest complete. Start the next set when you are ready.',true);}}
function processPose(points,now){const cfg=EXERCISES[exercise];if(!points){if(checkingCamera){readiness.update(false,now);$('readiness-progress').value=0;$('readiness-text').textContent='No person detected. Move into the frame with your full body visible.';}counter.update(NaN,0,now);$('tracking-status').textContent='No pose detected · move into frame';$('angle-live').textContent='—';renderMetrics(0);feedback('Move into the frame and keep the required joints visible.',true);return;}

const {ids,scaled,conf,deg}=poseMeasurement(exercise,points,mode==='camera'?video.videoWidth:960,mode==='camera'?video.videoHeight:600);if(checkingCamera){const startValid=conf>=.65&&deg>=(exercise==='plank'?160:cfg.up);const ready=readiness.update(startValid,now);drawPose(points,conf,ids);renderMetrics(conf);$('readiness-progress').value=readiness.progress(now);$('readiness-text').textContent=conf<.65?'Show all required joints. Move back, improve lighting, and follow the camera view in the form tips.':!startValid?'Joints visible. '+cfg.setup:'Start position found. Hold steady for a moment.';$('tracking-status').textContent='Checking camera position';if(!ready)return;checkingCamera=false;counter.resetCycle();$('readiness-title').textContent='Ready to train';$('readiness-text').textContent='Required joints and start position checked. Begin your set.';lastSpeak=-Infinity;feedback('Position ready. Begin your set.',true);return;}const counted=counter.update(deg,conf,now);drawPose(points,conf,ids);renderMetrics(conf);$('angle-live').textContent=conf>=.65?Math.round(deg)+'°':'—';$('tracking-status').textContent=conf>=.65?(mode==='demo'?'Simulated landmarks':'Pose tracked')+' · '+counter.phase:'Tracking paused · improve framing';if(conf<.65){feedback('Keep the required joints inside the frame. Counting is paused until tracking improves.',true);return;}confidenceSum+=conf;confidenceN++;if(now-lastSample>80){samples.push({t:elapsed,a:deg});samples=samples.filter(s=>elapsed-s.t<15000);lastSample=now;}

if((exercise==='plank'?counter.seconds:counter.reps)>=target()){completeSet();return;}
if(exercise==='plank'){feedback(deg>=160?'Hold steady. Keep breathing.':'Bring shoulders, hips and ankles into a straight, horizontal line.',true);if(counter.seconds>=target()&&!counter.goalAnnounced){counter.goalAnnounced=true;lastSpeak=-Infinity;feedback('Hold target reached. Finish the session when you are ready.',true);}}

else if(counted){feedback(counter.reps===target()?`Target reached. ${counter.reps} complete repetitions. Finish the session to save your workout.`:`Rep ${counter.reps} complete. Keep the next movement controlled.`,true);}

else if(exercise==='press'||exercise==='pullup'){feedback(counter.stage==='seek'?'Extend your arms overhead to find the start position.':counter.stage==='top'?'Bend your elbows with control.':'Return to extended arms to finish the repetition.');}

else if(exercise==='squat'){feedback(counter.stage==='seek'?'Stand tall to begin. Keep a side view so the knee angle can reach 150°.':counter.stage==='top'?`Start position found. Bend comfortably below 115°. Current knee angle: ${Math.round(deg)}°.`:`Bend detected. Stand tall above 150° to complete the rep. Current knee angle: ${Math.round(deg)}°.`);}

else if(exercise==='pushup'){const hip=ids[0]===11?23:24,ankle=ids[0]===11?27:28;const body=angle(scaled[ids[0]],scaled[hip],scaled[ankle]);if(body<150)feedback('Try to keep your shoulders, hips and ankles in a straighter line.',true);}

else if(exercise==='curl'){const shoulder=scaled[ids[0]],elbow=scaled[ids[1]];if(Math.abs(elbow.x-shoulder.x)>Math.abs(elbow.y-shoulder.y)*.65)feedback('Keep your upper arm closer to your torso as you curl.',true);}}

function drawPose(points,conf,ids){ctx.clearRect(0,0,960,600);const vw=mode==='camera'?video.videoWidth:960,vh=mode==='camera'?video.videoHeight:600;const scale=Math.min(960/vw,600/vh),ox=(960-vw*scale)/2,oy=(600-vh*scale)/2;const xy=p=>[ox+(mode==='camera'?1-p.x:p.x)*vw*scale,oy+p.y*vh*scale];ctx.lineWidth=3;ctx.strokeStyle=conf>=.65?'#91dcb9':'#e9b768';ctx.shadowColor='#96ffc0';ctx.shadowBlur=6;connections.forEach(([a,b])=>{if((points[a]?.visibility||0)<.5||(points[b]?.visibility||0)<.5)return;ctx.beginPath();ctx.moveTo(...xy(points[a]));ctx.lineTo(...xy(points[b]));ctx.stroke();});points.forEach((p,i)=>{if((p.visibility||0)<.5||i<11)return;ctx.beginPath();ctx.arc(...xy(p),ids.includes(i)?7:4,0,2*Math.PI);ctx.fillStyle=ids.includes(i)?'#c3ff7f':'#d2ede1';ctx.fill();});ctx.shadowBlur=0;if(mode==='demo'){ctx.fillStyle='#829f91';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('GUIDED MOVEMENT SIMULATION',480,515);}}

function simulated(t){return guidePose(exercise,t);}

function drawChart(){cx.clearRect(0,0,850,100);cx.strokeStyle='#2b3630';cx.lineWidth=1;for(let y=20;y<100;y+=30){cx.beginPath();cx.moveTo(0,y);cx.lineTo(850,y);cx.stroke();}if(samples.length<2)return;cx.strokeStyle='#b5f469';cx.lineWidth=2;cx.beginPath();samples.forEach((s,i)=>{const x=850-(elapsed-s.t)/15000*850,y=90-s.a/180*75;i?cx.lineTo(x,y):cx.moveTo(x,y);});cx.stroke();}

function tick(now){const dt=Math.min(100,now-lastTick);lastTick=now;updateRest(now);if(mode&&!paused){if(!checkingCamera)elapsed+=dt;$('timer').textContent=timeText(elapsed);try{if(mode==='demo'){demoTime+=dt;processPose(simulated(demoTime),now);}else if(video.readyState>=2&&lastFrame!==video.currentTime){lastFrame=video.currentTime;const result=model.detectForVideo(video,now);processPose(result.landmarks[0],now);}}catch{pause();feedback('Tracking was interrupted. Finish this session and restart the camera.');}drawChart();}requestAnimationFrame(tick);}requestAnimationFrame(tick);

function view(name){document.querySelectorAll('.view').forEach(v=>v.hidden=v.id!==name+'-view');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('page-title').replaceChildren(document.createTextNode({coach:'Live coach',history:'Workout history',about:'Project overview'}[name]));const dot=document.createElement('span');dot.className='accent';dot.textContent='.';$('page-title').append(dot);if(name!=='coach'&&mode&&!paused)pause();if(name==='history')renderHistory();}

function renderHistory(){const week=weeklyProgress(history);$('history-summary').replaceChildren(...[[week.sessions,'Workouts'],[week.sets,'Completed sets'],[week.reps,'Repetitions'],[week.holds+'s','Plank holds']].map(([n,label])=>{const a=document.createElement('article'),b=document.createElement('strong'),s=document.createElement('span');b.textContent=n;s.textContent=label;a.append(b,s);return a;}));const max=Math.max(1,...week.days.map(d=>d.sessions));$('weekly-chart').replaceChildren(...week.days.map(d=>{const a=document.createElement('div'),bar=document.createElement('div'),label=document.createElement('span');a.className='weekly-day';bar.className='weekly-bar';bar.style.height=(8+d.sessions/max*90)+'px';bar.textContent=d.sessions;label.textContent=d.label;a.setAttribute('aria-label',d.label+': '+d.sessions+' workouts');a.append(bar,label);return a;}));$('history-empty').hidden=history.length>0;$('history-body').replaceChildren(...history.map(s=>{const tr=document.createElement('tr');[new Date(s.date).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}),EXERCISES[s.exercise]?.name||s.exercise,s.exercise==='plank'?`${s.holdSeconds||0}s / ${s.target*(s.setsTarget||1)}s`:`${s.reps} / ${s.target*(s.setsTarget||1)}`,`${s.setsCompleted??((s.exercise==='plank'?(s.holdSeconds||0):s.reps)>=s.target?1:0)} / ${s.setsTarget||1}`,timeText(s.duration*1000),s.source==='demo'?'Simulated demo':'Live camera'].forEach((t,i)=>{const td=document.createElement('td');td.textContent=t;if(i===5&&s.source==='demo')td.className='demo-label';tr.append(td);});return tr;}));$('export').disabled=!history.length;}

function exportCSV(){const rows=[['Date','Exercise','Reps','Hold seconds','Target per set','Sets planned','Sets completed','Results per set','Duration seconds','Source','Mean landmark confidence %'],...history.map(s=>[s.date,EXERCISES[s.exercise]?.name,s.reps,s.holdSeconds??'',s.target,s.setsTarget||1,s.setsCompleted??((s.exercise==='plank'?(s.holdSeconds||0):s.reps)>=s.target?1:0),(s.setResults||[]).join(';'),s.duration,s.source,s.confidence??''])];const blob=new Blob([rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='exercise-intelligence-workouts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

document.querySelectorAll('[data-exercise]').forEach(b=>b.onclick=()=>setExercise(b.dataset.exercise));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('project-button').onclick=()=>view('about');$('back-coach').onclick=()=>view('coach');$('start-camera').onclick=enableCamera;$('start-demo').onclick=()=>{if(!mode&&!busy)begin('demo');};$('pause').onclick=pause;$('finish').onclick=()=>stop();$('target-minus').onclick=()=>setTarget(target()-1);$('target-plus').onclick=()=>setTarget(target()+1);$('target').onchange=()=>setTarget(target());$('export').onclick=exportCSV;document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>feedback(b.dataset.prompt==='setup'||exercise==='plank'?EXERCISES[exercise].setup:`Begin extended above ${EXERCISES[exercise].up} degrees, bend below ${EXERCISES[exercise].down} degrees, then return. Both endpoints must be stable. Incomplete cycles do not count.`,true));$('voice').onchange=()=>{saveVoice();if($('voice').checked){lastSpeak=-Infinity;feedback('Voice coaching is on. '+EXERCISES[exercise].setup,true);}else if('speechSynthesis'in window)speechSynthesis.cancel();};document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode&&!paused)pause();});window.addEventListener('beforeunload',()=>stream?.getTracks().forEach(t=>t.stop()));setExercise('squat');drawChart();


$('sets-minus').onclick=()=>setSets(setCount()-1);$('sets-plus').onclick=()=>setSets(setCount()+1);$('sets').onchange=()=>setSets(setCount());$('next-set').onclick=nextSet;

$('offline-voices').onchange=voices;$('reload-voices').onclick=voices;$('rest-seconds').onchange=()=>{$('rest-seconds').value=Math.max(0,Math.min(300,Math.round(Number($('rest-seconds').value)||0)));};
